        "desc": "Une expérience cinématographique viscérale et transcendante ! Iñárritu nous plonge sans concession dans une nature aussi belle que cruelle, et DiCaprio livre une performance physique d'une intensité jamais vue. La photographie naturelle d'Emmanuel Lubezki est tout simplement révolutionnaire. Un chef-d'œuvre brutal et poétique.",
        "subType": 1,
        "type": 18,
        "verso": "The Revenant (2015)"
